{"task": "Find log messages mentioning .log files", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '\\.log\\b')"}
{"task": "Find log messages mentioning configuration files like .conf or .cfg", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '\\.(conf|cfg)\\b', 'i')"}
{"task": "Count error-level log messages mentioning SQL script files", "sql": "SELECT count(*) AS sql_file_errors FROM logs WHERE level = 'ERROR' AND regexp_like(message, '\\.sql\\b')"}
{"task": "List distinct services whose logs mention compressed archive files", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(message, '\\.(zip|tar|gz|rar)\\b', 'i')"}
{"task": "Tag each log line with whether it references an image file extension", "sql": "SELECT ts, message, CASE WHEN regexp_like(message, '\\.(png|jpg|jpeg|gif|svg)\\b', 'i') THEN 'image' ELSE 'other' END AS file_type FROM logs"}
{"task": "Find request paths that reference executable or script file extensions, a potential security concern", "sql": "SELECT id, user_id, path, status FROM events WHERE regexp_like(path, '\\.(php|exe|sh|bat)(\\?|$)', 'i')"}
{"task": "Get hourly counts of log lines mentioning Java class or jar files", "sql": "SELECT date_trunc('hour', ts) AS hr, count(*) AS mentions FROM logs WHERE regexp_like(message, '\\.(class|jar)\\b') GROUP BY hr ORDER BY hr"}
{"task": "Find warning or error logs referencing YAML or JSON config files", "sql": "SELECT ts, level, message FROM logs WHERE level IN ('WARN', 'ERROR') AND regexp_like(message, '\\.(yml|yaml|json)\\b', 'i')"}
{"task": "Find events paths requesting backup or temp file extensions that may indicate scanning attempts", "sql": "SELECT id, path, status FROM events WHERE regexp_like(path, '\\.(bak|tmp|old)(\\?|$)', 'i') AND status = 404"}
{"task": "Rank services by how often their logs mention PDF or DOCX document files", "sql": "SELECT service, count(*) AS doc_mentions FROM logs WHERE regexp_like(message, '\\.(pdf|docx?)\\b', 'i') GROUP BY service ORDER BY doc_mentions DESC"}

